<?php

namespace App\Http\Controllers;

use Illuminate\Http\Request;
use App\Models\Vehicle;
use App\Models\Booking;
use App\Models\Invoice;
use App\Models\VehicleCategory;
use Illuminate\Support\Facades\DB;

class ReportController extends Controller
{
    public function profitability()
    {
        $vehicles = Vehicle::with(['model.brand', 'category'])
            ->withCount('bookings')
            ->get()
            ->map(function ($vehicle) {
                // Total revenue generated by vehicle
                $revenue = Invoice::whereHas('booking', fn($q) => $q->where('assigned_vehicle_id', $vehicle->id))->sum('paid_amount');
                $maintenanceCost = $vehicle->maintenanceRecords()->where('status', 'completed')->count() * 4500; // estimated baseline or actual work orders
                $estimatedFuelInsurance = 12000.00; // estimated annual baseline
                $netProfit = $revenue - ($maintenanceCost + $estimatedFuelInsurance);

                return [
                    'vehicle' => $vehicle,
                    'total_trips' => $vehicle->bookings_count,
                    'revenue' => $revenue,
                    'maintenance_cost' => $maintenanceCost,
                    'total_expenses' => $maintenanceCost + $estimatedFuelInsurance,
                    'net_profit' => $netProfit,
                    'roi_percentage' => $revenue > 0 ? round(($netProfit / $revenue) * 100, 1) : 0,
                ];
            });

        return view('reports.profitability', compact('vehicles'));
    }

    public function fleetUtilization()
    {
        $categories = VehicleCategory::withCount([
            'vehicles as total_fleet',
            'vehicles as rented_count' => fn($q) => $q->where('status', 'rented'),
            'vehicles as available_count' => fn($q) => $q->where('status', 'available'),
            'vehicles as maintenance_count' => fn($q) => $q->whereIn('status', ['maintenance', 'in_repair']),
        ])->get();

        return view('reports.utilization', compact('categories'));
    }
}

